+			options: [
+				{ label: "Start a new run (recommended)", description: "A run makes the fix." },
+				{ label: "Edit the sentence only", description: "Faster." },
+			],
+			multiple: false,
+			blocks: [{ index: 2, digest: digests[2]! }],
+		}],
+	});
+	return result.decisions[0]!.id;
